struct Money {
    int cents;
    // Implement both operators here.
};

answer:
struct Money {
    int cents;
    Money operator+(const Money& rhs) const {
        return Money{cents + rhs.cents};
    }
    Money& operator+=(const Money& rhs) {
        cents += rhs.cents;
        return *this;
    }
};

